Definition calldata_slice_length (s : CalldataSlice) : source_length :=
   match s with
   | InputCalldata (@existT _ _ len (@existT _ _ off bytes)) =>
      bytes.(StatelessInputSliceFields_len)
   | MemoryCalldata (@existT _ _ len (@existT _ _ off bytes)) => bytes.(MemorySliceFields_len)
   end.

Definition stateless_input_slice_length {ex489901_ : Z} {ex489900_ : Z}
(s : StatelessInputSliceFields ex489900_ ex489901_) (*(0 <=? ex489900_) && (0 <=? ex489901_)*)
: source_length :=
   s.(StatelessInputSliceFields_len).

