Definition stateless_input_slice (off : Z) (len : Z) (*(0 <=? off) && (0 <=? len)*)
: StatelessInputSliceFields off len :=
   {| StatelessInputSliceFields_off := off;  StatelessInputSliceFields_len := len |}.

Definition scratch_slice (off : Z) (len : Z) (*(0 <=? off) && (0 <=? len)*)
: ScratchSliceFields off len :=
   {| ScratchSliceFields_off := off;  ScratchSliceFields_len := len |}.

Definition memory_slice (off : Z) (len : Z) (*(0 <=? off) && (0 <=? len)*)
: MemorySliceFields off len :=
