Definition output_slice (off : Z) (len : Z) (*(0 <=? off) && (0 <=? len)*)
: OutputSliceFields off len :=
   {| OutputSliceFields_off := off;  OutputSliceFields_len := len |}.

Definition EMPTY_STATELESS_INPUT_SLICE : StatelessInputSliceFields 0 0 :=
stateless_input_slice (0) (0).
