Definition stateless_input_sub_slice {base : Z} {source_len : Z}
(s : StatelessInputSliceFields base source_len) (off : Z) (len : Z)
(*(0 <=? base) && (0 <=? source_len) &&
  ((0 <=? off) && ((0 <=? len) && ((off + len) <=? source_len)))*)
: StatelessInputSliceFields (base + off) len :=
   stateless_input_slice ((Z.add base (off))) (len).

Definition scratch_sub_slice {base : Z} {source_len : Z}
(s : ScratchSliceFields base source_len) (off : Z) (len : Z)
(*(0 <=? base) && (0 <=? source_len) &&
  ((0 <=? off) && ((0 <=? len) && ((off + len) <=? source_len)))*)
: ScratchSliceFields (base + off) len :=
   scratch_slice ((Z.add base (off))) (len).

Definition memory_sub_slice {base : Z} {source_len : Z}
(s : MemorySliceFields base source_len) (off : Z) (len : Z)
(*(0 <=? base) && (0 <=? source_len) &&
  ((0 <=? off) && ((0 <=? len) && ((off + len) <=? source_len)))*)
: MemorySliceFields (base + off) len :=
   memory_slice ((Z.add base (off))) (len).

Definition code_region_sub_slice {base : Z} {source_len : Z}
(s : CodeRegionSliceFields base source_len) (off : Z) (len : Z)
(*(0 <=? base) && (0 <=? source_len) &&
  ((0 <=? off) && ((0 <=? len) && ((off + len) <=? source_len)))*)
: CodeRegionSliceFields (base + off) len :=
   code_region_slice ((Z.add base (off))) (len).

Definition log_data_sub_slice {base : Z} {source_len : Z}
(s : LogDataSliceFields base source_len) (off : Z) (len : Z)
(*(0 <=? base) && (0 <=? source_len) &&
  ((0 <=? off) && ((0 <=? len) && ((off + len) <=? source_len)))*)
: LogDataSliceFields (base + off) len :=
   log_data_slice ((Z.add base (off))) (len).

Definition calldata_sub_slice (s : CalldataSlice) (off : Z) (len : Z) (*(0 <=? off) && (0 <=? len)*)
: M (CalldataSlice) :=
   match s with
   | InputCalldata (@existT _ _ syn_len (@existT _ _ syn_off bytes)) =>
      (if Z.leb ((Z.add (off) (len))) (bytes.(StatelessInputSliceFields_len)) then
         returnM ((InputCalldata
                     (@existT _ _ _ (@existT _ _ _ (stateless_input_sub_slice (bytes) (off) (len))))))
       else assert_exp' false "calldata sub-slice bounds" >>= fun _ => exit tt)
       : M (CalldataSlice)
   | MemoryCalldata (@existT _ _ syn_len (@existT _ _ syn_off bytes)) =>
      (if Z.leb ((Z.add (off) (len))) (bytes.(MemorySliceFields_len)) then
         returnM ((MemoryCalldata
                     (@existT _ _ _ (@existT _ _ _ (memory_sub_slice (bytes) (off) (len))))))
       else assert_exp' false "calldata sub-slice bounds" >>= fun _ => exit tt)
       : M (CalldataSlice)
   end
    : M (CalldataSlice).

Definition stateless_input_slice_suffix {base : Z} {source_len : Z}
(s : StatelessInputSliceFields base source_len) (off : Z)
(*(0 <=? base) && (0 <=? source_len) && ((0 <=? off) && (off <=? source_len))*)
: StatelessInputSliceFields (base + off) (source_len - off) :=
   stateless_input_slice ((Z.add base (off))) ((Z.sub source_len (off))).

Definition scratch_slice_suffix {base : Z} {source_len : Z}
(s : ScratchSliceFields base source_len) (off : Z)
(*(0 <=? base) && (0 <=? source_len) && ((0 <=? off) && (off <=? source_len))*)
: ScratchSliceFields (base + off) (source_len - off) :=
   scratch_slice ((Z.add base (off))) ((Z.sub source_len (off))).

Definition undefined_ExceptionKind '(tt : unit) : M (ExceptionKind) :=
   (internal_pick
      ([StackUnderflow;
      StackOverflow;
      OutOfGas;
      InvalidOpcode;
      InvalidJump;
      StaticViolation;
      CallDepthExceeded;
      InsufficientBalance;
      WriteProtection;
      InitCodeTooLarge;
      NonceOverflow;
      AddressCollision]))
    : M (ExceptionKind).

Definition undefined_BlockError '(tt : unit) : M (BlockError) :=
   (internal_pick
      ([InvalidConfig;
      HeaderChainBroken;
      RlpDecode;
      InvalidSignature;
      InvalidGasLimit;
      GasUsedExceedsLimit;
      BlobGasLimitExceeded;
      ExecutionInvalid;
      InvalidGasUsed;
      InvalidBlobGasUsed;
      InvalidExcessBlobGas;
      InvalidStateRoot;
      InvalidReceiptsRoot;
      InvalidLogsBloom;
      InvalidBlockHash;
      InvalidParentHash;
      BlockAccessListTooLarge;
      InvalidBlockAccessList;
      InvalidExecutionRequests;
      WitnessDeficient]))
    : M (BlockError).

