Definition code_slice {off : Z} {len : Z} (bytes : CodeRegionSliceFields off len)
(*(0 <=? off) && (0 <=? len) && (0 <=? len)*)
: CodeSlice :=
   @existT _ _ len (@existT _ _ off (bytes)).

Definition validated_code_slice {ex490225_ : Z} {ex490224_ : Z}
(bytes : CodeRegionSliceFields ex490224_ ex490225_) (*(0 <=? ex490224_) && (0 <=? ex490225_)*)
: CodeSlice :=
