Definition stateless_input_slice_byte {ex490468_ : Z} {ex490467_ : Z}
(s : StatelessInputSliceFields ex490467_ ex490468_) (off : Z) (*0 <=? off*)
(*(0 <=? ex490467_) && (0 <=? ex490468_)*)
: M (byte) :=
   (if Z.ltb (off) ex490468_ return M (mword 8) then
      (stateless_input_byte_at (@existT _ _ ex490468_ (@existT _ _ ex490467_ (s))) (off))
       : M (mword 8)
    else returnM ((Ox"00")))
    : M (mword 8).

