   (host_scratch_store_fixed_bytes_256 (arena.(ScratchSliceFields_len)) (data)) >>= fun w__0 =>
   match w__0 with
   | ScratchRegionReady (@existT _ _ __arena1 (@existT _ _ __arena0 expanded)) =>
      write_reg scratch_arena (@existT _ _ _ (@existT _ _ _ (expanded)))  : M (unit)
   | ScratchRegionFailed tt => assert_exp' false "scratch fixed-byte append" >>= fun _ => exit tt
   end
    : M (unit).

Definition scratch_push_word_be (data : word) (len : Z) (*(0 <=? data) && (data <=? (2 ^ 256 - 1))*)
(*(0 <=? len) && (len <=? 32)*)
: M (unit) :=
   let data := (data).(word_value) in
   (if neq_int (len) (0) return M (unit) then
      read_reg scratch_arena >>= fun '(@existT _ _ __arena1 (@existT _ _ __arena0 arena)) =>
      (host_scratch_store_word (arena.(ScratchSliceFields_len)) (Build_word ((data))) (len)) >>= fun w__0 =>
      match w__0 with
      | ScratchRegionReady (@existT _ _ __arena1 (@existT _ _ __arena0 expanded)) =>
         write_reg scratch_arena (@existT _ _ _ (@existT _ _ _ (expanded)))  : M (unit)
      | ScratchRegionFailed tt => assert_exp' false "scratch word append" >>= fun _ => exit tt
      end
       : M (unit)
    else returnM (tt))
    : M (unit).

Definition scratch_finish (start : Z) (*0 <=? start*) : M (ScratchSlice) :=
   let start_offset := start in
   read_reg scratch_arena >>= fun '(@existT _ _ __arena1 (@existT _ _ __arena0 arena)) =>
   let stop_offset := arena.(ScratchSliceFields_len) in
   (if Z.leb (start_offset) (stop_offset) then
      returnM ((@existT _ _ _ (@existT _ _ _ (scratch_sub_slice (arena) (start)
                                                ((Z.sub (stop_offset) (start_offset)))))) : {__arena1 & {__arena0 & (ScratchSliceFields __arena0 __arena1)}}%type)
    else assert_exp' false "scratch finish mark" >>= fun _ => exit tt)
    : M ({__arena1 & {__arena0 & (ScratchSliceFields __arena0 __arena1)}}%type).

Definition scratch_rewind (mark : Z) (*0 <=? mark*) : M (unit) :=
   let mark_offset := mark in
   read_reg scratch_arena >>= fun '(@existT _ _ __arena1 (@existT _ _ __arena0 arena)) =>
   let cursor_offset := arena.(ScratchSliceFields_len) in
   (if Z.leb (mark_offset) (cursor_offset) return M (unit) then
      write_reg scratch_arena (@existT _ _ _ (@existT _ _ _ (scratch_sub_slice (arena) (0) (mark)))) >>
      (host_scratch_truncate (mark))
       : M (unit)
    else assert_exp' false "scratch rewind mark" >>= fun _ => exit tt)
    : M (unit).

Definition scratch_reset '(tt : unit) : M (unit) :=
   write_reg scratch_arena (@existT _ _ 0 (@existT _ _ 0 (EMPTY_SCRATCH_SLICE))) >>
   (host_scratch_truncate (0))
    : M (unit).

