Axiom stateless_input_keccak256 :
  forall

  (_ : StatelessInputSlice)
  (*(0 <=? ex556397_) && (0 <=? ex556398_)*),
  M (hash).

Axiom scratch_keccak256 :
  forall

  (_ : ScratchSlice)
  (*(0 <=? ex556401_) && (0 <=? ex556402_)*),
  M (hash).

Axiom memory_keccak256 :
  forall

  (_ : MemorySlice)
  (*(0 <=? ex556405_) && (0 <=? ex556406_)*),
  M (hash).

Axiom code_keccak256 :
  forall

  (_ : CodeRegionSlice)
  (*(0 <=? ex556409_) && (0 <=? ex556410_)*),
  M (hash).

Axiom output_keccak256 :
  forall

  (_ : OutputSlice)
  (*(0 <=? ex556413_) && (0 <=? ex556414_)*),
  M (hash).

Axiom log_data_keccak256 :
  forall

  (_ : LogDataSlice)
  (*(0 <=? ex556417_) && (0 <=? ex556418_)*),
  M (hash).

Axiom stateless_input_sha256 :
  forall

  (_ : StatelessInputSlice)
  (*(0 <=? ex556421_) && (0 <=? ex556422_)*),
  M (hash).

Axiom scratch_sha256 :
  forall

  (_ : ScratchSlice)
  (*(0 <=? ex556425_) && (0 <=? ex556426_)*),
  M (hash).

Axiom memory_sha256 : forall  (_ : MemorySlice) (*(0 <=? ex556429_) && (0 <=? ex556430_)*), M (hash).

Definition calldata_keccak256 (input : CalldataSlice) : M (hash) :=
   match input with
   | InputCalldata (@existT _ _ len (@existT _ _ off bytes)) =>
      (stateless_input_keccak256 (@existT _ _ _ (@existT _ _ _ (bytes))))  : M (vec (mword 8) 32)
   | MemoryCalldata (@existT _ _ len (@existT _ _ off bytes)) =>
      (memory_keccak256 (@existT _ _ _ (@existT _ _ _ (bytes))))  : M (vec (mword 8) 32)
   end
    : M (vec (mword 8) 32).

Definition calldata_sha256 (input : CalldataSlice) : M (hash) :=
   match input with
   | InputCalldata (@existT _ _ len (@existT _ _ off bytes)) =>
      (stateless_input_sha256 (@existT _ _ _ (@existT _ _ _ (bytes))))  : M (vec (mword 8) 32)
   | MemoryCalldata (@existT _ _ len (@existT _ _ off bytes)) =>
      (memory_sha256 (@existT _ _ _ (@existT _ _ _ (bytes))))  : M (vec (mword 8) 32)
   end
    : M (vec (mword 8) 32).

Axiom keccak256_word :
  forall

  (_ : word)
  (*(0 <=? ex556447_) && (ex556447_ <=? (2 ^ 256 - 1))*),
  M (hash).

Axiom keccak256_address : forall  (_ : address_typ) , M (hash).

Axiom sha256_pair : forall  (_ : hash) (_ : hash) , M (hash).

