Definition NO_BLOB_SCHEDULE : BlobSchedule :=
{| BlobSchedule_target := (Build_blob_target_count (0));
   BlobSchedule_max := (Build_blob_count (0));
   BlobSchedule_base_fee_update_fraction := (Build_blob_fee_update_fraction (1)) |}.
#[export] Hint Unfold NO_BLOB_SCHEDULE : sail.
Definition protocol_profile (schema_fork : mword 8) : M (ProtocolProfile) :=
   (if eq_vec (schema_fork) ((Ox"0A")) then
      returnM (({| ProtocolProfile_fork := Berlin;
                   ProtocolProfile_blob_schedule := NO_BLOB_SCHEDULE |}))
    else if orb ((eq_vec (schema_fork) ((Ox"0B"))))
              ((orb ((eq_vec (schema_fork) ((Ox"0C")))) ((eq_vec (schema_fork) ((Ox"0D")))))) then
      returnM (({| ProtocolProfile_fork := London;
                   ProtocolProfile_blob_schedule := NO_BLOB_SCHEDULE |}))
    else if eq_vec (schema_fork) ((Ox"0E")) then
      returnM (({| ProtocolProfile_fork := Paris;
                   ProtocolProfile_blob_schedule := NO_BLOB_SCHEDULE |}))
    else if eq_vec (schema_fork) ((Ox"0F")) then
      returnM (({| ProtocolProfile_fork := Shanghai;
                   ProtocolProfile_blob_schedule := NO_BLOB_SCHEDULE |}))
    else if eq_vec (schema_fork) ((Ox"10")) then
      returnM (({| ProtocolProfile_fork := Cancun;
                   ProtocolProfile_blob_schedule :=
                     {| BlobSchedule_target := (Build_blob_target_count (3));
                        BlobSchedule_max := (Build_blob_count (6));
                        BlobSchedule_base_fee_update_fraction :=
                          (Build_blob_fee_update_fraction (3338477)) |} |}))
    else if orb ((eq_vec (schema_fork) ((Ox"11")))) ((eq_vec (schema_fork) ((Ox"12")))) then
      returnM (({| ProtocolProfile_fork := if eq_vec (schema_fork) ((Ox"11")) then Prague else Osaka;
                   ProtocolProfile_blob_schedule :=
                     {| BlobSchedule_target := (Build_blob_target_count (6));
                        BlobSchedule_max := (Build_blob_count (9));
                        BlobSchedule_base_fee_update_fraction :=
                          (Build_blob_fee_update_fraction (5007716)) |} |}))
    else if eq_vec (schema_fork) ((Ox"13")) then
      returnM (({| ProtocolProfile_fork := Osaka;
                   ProtocolProfile_blob_schedule :=
                     {| BlobSchedule_target := (Build_blob_target_count (10));
                        BlobSchedule_max := (Build_blob_count (15));
                        BlobSchedule_base_fee_update_fraction :=
                          (Build_blob_fee_update_fraction (8346193)) |} |}))
    else if eq_vec (schema_fork) ((Ox"14")) then
      returnM (({| ProtocolProfile_fork := Osaka;
                   ProtocolProfile_blob_schedule :=
                     {| BlobSchedule_target := (Build_blob_target_count (14));
                        BlobSchedule_max := (Build_blob_count (21));
                        BlobSchedule_base_fee_update_fraction :=
                          (Build_blob_fee_update_fraction (11684671)) |} |}))
    else if eq_vec (schema_fork) ((Ox"15")) then
      returnM (({| ProtocolProfile_fork := Amsterdam;
                   ProtocolProfile_blob_schedule :=
                     {| BlobSchedule_target := (Build_blob_target_count (14));
                        BlobSchedule_max := (Build_blob_count (21));
                        BlobSchedule_base_fee_update_fraction :=
                          (Build_blob_fee_update_fraction (11684671)) |} |}))
    else throw (InvalidBlock (InvalidConfig)))
    : M (ProtocolProfile).

