Fixpoint _rec_analyze_code_from {ex491165_ : Z} {ex491164_ : Z}
(code : CodeRegionSliceFields ex491164_ ex491165_) (fork : Fork) (table : jump_table_index) (pc : Z)
(analysis : CodeAnalysis) (_reclimit : Z) (*0 <=? pc*)
(*(0 <=? ex491164_) && (0 <=? ex491165_) && (0 <=? ex491165_)*)
(*(0 <=? table) && (table <=? (2 ^ 64 - 1))*) (_acc : Acc (Zwf 0) _reclimit)
{struct _acc} : M (unit).
exact (
   let table := (table).(jump_table_index_value) in
   assert_exp' (Z.geb (_reclimit) (0)) "recursion limit reached" >>= fun _ =>
   let position := pc in
   let code_len := code.(CodeRegionSliceFields_len) in
   (if Z.ltb (position) ex491165_ return M (unit) then
      let chunk := analysis.(CodeAnalysis_chunk) in
      let chunk_index := analysis.(CodeAnalysis_chunk_index) in
      let chunk_offset : Z := analysis.(CodeAnalysis_chunk_offset) in
      (code_slice_byte (code) (position)) >>= fun opcode =>
      let chunk : mword 256 :=
        if eq_vec (opcode) ((Ox"5B")) then or_vec (chunk) ((jumpdest_bit (chunk_offset)))
        else chunk in
      let opcode_value := uint (opcode) in
      (if andb ((Z.leb (96) (opcode_value))) ((Z.leb (opcode_value) (127))) then
         returnM ((Z.sub (opcode_value) (94)))
       else if andb ((fork_gteq (fork) (Amsterdam)))
                 ((orb ((Z.eqb (opcode_value) (230))) ((Z.eqb (opcode_value) (231)))))
         return
         M (Z) then
         (code_slice_byte (code) ((Z.add (position) (1)))) >>= fun (w__0 : mword 8) =>
         let w__1 : Z := if deep_stack_immediate_valid (w__0) then 2 else 1 in
         returnM (w__1)
       else if andb ((fork_gteq (fork) (Amsterdam))) ((Z.eqb (opcode_value) (232)))
         return
         M (Z) then
         (code_slice_byte (code) ((Z.add (position) (1)))) >>= fun (w__2 : mword 8) =>
         let w__3 : Z := if exchange_immediate_valid (w__2) then 2 else 1 in
         returnM (w__3)
       else returnM (1)) >>= fun (step : Z) =>
      (if Z.ltb (step) ((Z.sub ex491165_ (position))) return M (unit) then
         let added := Z.add (position) (step) in
         let progressed : Z := Z.add (chunk_offset) (step) in
         (if Z.ltb (progressed) (256) return M (unit) then
            (_rec_analyze_code_from _ _ (code) (fork) (Build_jump_table_index ((table))) (added)
               (({| CodeAnalysis_chunk := chunk;
                    CodeAnalysis_chunk_index := chunk_index;
                    CodeAnalysis_chunk_offset := progressed |})) ((Z.sub (_reclimit) (1)))
               (_limit_reduces_bool _acc ltac:(assumption)))
             : M (unit)
          else
            (store_jumpdest_chunk (Build_jump_table_index ((table))) ex491165_
               (({| CodeAnalysis_chunk := chunk;
                    CodeAnalysis_chunk_index := chunk_index;
                    CodeAnalysis_chunk_offset := chunk_offset |}))) >>
            (_rec_analyze_code_from _ _ (code) (fork) (Build_jump_table_index ((table))) (added)
               (({| CodeAnalysis_chunk := EMPTY_JUMPDEST_CHUNK;
                    CodeAnalysis_chunk_index := e_div (added) (256);
                    CodeAnalysis_chunk_offset := Z.sub (progressed) (256) |}))
               ((Z.sub (_reclimit) (1))) (_limit_reduces_bool _acc ltac:(assumption)))
             : M (unit))
          : M (unit)
       else
         (store_jumpdest_chunk (Build_jump_table_index ((table))) ex491165_
            (({| CodeAnalysis_chunk := chunk;
                 CodeAnalysis_chunk_index := chunk_index;
                 CodeAnalysis_chunk_offset := chunk_offset |})))
          : M (unit))
       : M (unit)
    else (store_jumpdest_chunk (Build_jump_table_index ((table))) ex491165_ (analysis))  : M (unit))
    : M (unit)
).
