      ((rlp_decode_u256 (w__0)) >>= fun semanticResult => returnM (semanticResult).(word_value))
       : M (Z))
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_word (semanticResult)).

Definition k_sload (a : vec (mword 8) 20) (s : word) (*(0 <=? s) && (s <=? (2 ^ 256 - 1))*)
: M (StorageValue) :=
   let s := (s).(word_value) in
   catch_early_return
     (let key := storage_key (a) (Build_word ((s))) in
     liftR ((storage_tx_get (key))) >>= fun tx_value =>
     match tx_value with
     | StorageTxHit value =>
        (early_return (value  : StorageValue) : MR StorageValue unit)  : MR (StorageValue) (unit)
     | StorageTxCleared _ =>
        liftR ((bal_storage_read (a) (Build_word ((s))))) >>
        (early_return (({| StorageValue_curr := (Build_word ((ZERO_WORD).(word_value)));
                           StorageValue_orig := (Build_word ((ZERO_WORD).(word_value))) |})
         : StorageValue) :
          MR StorageValue unit)
         : MR (StorageValue) (unit)
     | StorageTxMiss _ =>
        liftR ((bal_storage_read (a) (Build_word ((s)))))  : MR (StorageValue) (unit)
     end >>
     liftR ((storage_block_get (key))) >>= fun block_value =>
     match block_value with
     | Some entry =>
        (early_return (({| StorageValue_curr :=
                             (Build_word ((entry.(StorageValue_curr)).(word_value)));
                           StorageValue_orig :=
                             (Build_word ((entry.(StorageValue_curr)).(word_value))) |})
         : StorageValue) :
          MR StorageValue unit)
         : MR (StorageValue) (unit)
     | None => returnR (StorageValue) (tt)
     end >>
     liftR ((k_aload (a))) >>= fun acc =>
     liftR ((keccak256_word (Build_word ((s))))) >>= fun slot_hash =>
     (if acc.(Account_storage_cleared) then returnR (StorageValue) ((ZERO_WORD).(word_value))
      else
        liftR (((stateless_storage_by_key (acc.(Account_info).(AccountInfo_storage_root))
                   (slot_hash)) >>= fun semanticResult =>
                returnM (semanticResult).(word_value)))
         : MR (StorageValue) (Z)) >>= fun value =>
     liftR ((storage_block_cache (key) (slot_hash) (Build_word ((value))))) >>
     returnR (StorageValue) (({| StorageValue_curr := (Build_word (value));
                                 StorageValue_orig := (Build_word (value)) |}))).

Definition k_sstore (a : vec (mword 8) 20) (s : word) (v : StorageValue)
(*(0 <=? s) && (s <=? (2 ^ 256 - 1))*)
: M (unit) :=
