Definition k_log_topics (topics : LogTopics) : M (unit) :=
   match topics with
   | LogTopics0 tt => returnM (tt)
   | LogTopics1 t0 => let t0 := (t0).(word_value) in (log_add_topic (Build_word ((t0))))  : M (unit)
   | LogTopics2 (t0, t1) =>
      let t0 := (t0).(word_value) in
      let t1 := (t1).(word_value) in
      (log_add_topic (Build_word ((t0)))) >> (log_add_topic (Build_word ((t1))))  : M (unit)
   | LogTopics3 (t0, t1, t2) =>
      let t0 := (t0).(word_value) in
      let t1 := (t1).(word_value) in
      let t2 := (t2).(word_value) in
      (log_add_topic (Build_word ((t0)))) >>
      (log_add_topic (Build_word ((t1)))) >> (log_add_topic (Build_word ((t2))))  : M (unit)
   | LogTopics4 (t0, t1, t2, t3) =>
      let t0 := (t0).(word_value) in
      let t1 := (t1).(word_value) in
      let t2 := (t2).(word_value) in
      let t3 := (t3).(word_value) in
      (log_add_topic (Build_word ((t0)))) >>
      (log_add_topic (Build_word ((t1)))) >>
      (log_add_topic (Build_word ((t2)))) >> (log_add_topic (Build_word ((t3))))  : M (unit)
   end
    : M (unit).

Definition k_log_data (data : LogData) : M (unit) :=
   match data with
   | LogDataMemory (@existT _ _ len (@existT _ _ off bytes)) =>
      (log_add_data_memory (@existT _ _ _ (@existT _ _ _ (bytes))))  : M (unit)
   | LogDataWord value =>
      let value := (value).(word_value) in (log_add_data_word (Build_word ((value))))  : M (unit)
   end
    : M (unit).

Definition k_log (a : vec (mword 8) 20) (topics : LogTopics) (data : LogData) : M (unit) :=
   (log_begin (a)) >> (k_log_topics (topics)) >> (k_log_data (data))  : M (unit).

Definition read_logs '(tt : unit) : M (LogSeriesRef) :=
   ((logs_tx_start (tt)) >>= fun semanticResult => returnM (semanticResult).(log_store_index_value)) >>= fun (w__0 : Z) =>
   ((logs_tx_count (tt)) >>= fun semanticResult => returnM (semanticResult).(log_store_index_value)) >>= fun (w__1 : Z) =>
   returnM (({| LogSeriesRef_start := (Build_log_store_index (w__0));
                LogSeriesRef_count := (Build_log_store_index (w__1)) |})).

Definition read_log_data (index : log_store_index) (*(0 <=? index) && (index <=? (2 ^ 64 - 1))*)
: M (LogDataSlice) :=
   let index := (index).(log_store_index_value) in
   ((log_data_offset (Build_log_store_index ((index)))) >>= fun semanticResult =>
    returnM (semanticResult).(log_store_index_value)) >>= fun off =>
   ((log_data_length (Build_log_store_index ((index)))) >>= fun semanticResult =>
    returnM (semanticResult).(log_store_index_value)) >>= fun len =>
   (if Z.leb (len) ((Z.sub ((Z.sub ((pow2 (64))) (1))) (off))) then
      returnM ((@existT _ _ len (@existT _ _ off (log_data_slice (off) (len)))) : {len & {off & (LogDataSliceFields off len)}}%type)
    else assert_exp' false "log data slice overflow" >>= fun _ => exit tt)
    : M ({len & {off & (LogDataSliceFields off len)}}%type).

Definition LOGS_BLOOM_BYTE_LENGTH : Z := 256.
#[export] Hint Unfold LOGS_BLOOM_BYTE_LENGTH : sail.
Definition bloom_bit_mask (bit_to_set : Z) (*(0 <=? bit_to_set) && (bit_to_set <=? 7)*) : byte :=
   shiftl ((Ox"01")) (bit_to_set).

Definition bloom_set_bit (bloom : vec (mword 8) 256) (bit_to_set : bloom_bit_index)
(*(0 <=? bit_to_set) && (bit_to_set <=? 2047)*)
: LogsBloom :=
   let bit_to_set := (bit_to_set).(bloom_bit_index_value) in
   let out := bloom in
   let quotient := e_div (bit_to_set) (8) in
   let natural_byte : Z := quotient in
   let remainder := Z.rem (bit_to_set) (8) in
   let bit_in_byte : Z := remainder in
   vec_update_dec (out) (natural_byte)
     ((or_vec ((vec_access_dec (out) (natural_byte))) ((bloom_bit_mask (bit_in_byte))))).

Definition bloom_add_entry_hash (bloom : vec (mword 8) 256) (h : vec (mword 8) 32) : LogsBloom :=
   let bytes := h in
   let out :=
     bloom_set_bit (bloom)
       (Build_bloom_bit_index (((uint
                                   ((concat_vec
                                       ((subrange_vec_dec ((vec_access_dec (bytes) (0))) (2) (0)))
                                       ((vec_access_dec (bytes) (1))))))))) in
   let out : vec (mword 8) 256 :=
     bloom_set_bit (out)
       (Build_bloom_bit_index (((uint
                                   ((concat_vec
                                       ((subrange_vec_dec ((vec_access_dec (bytes) (2))) (2) (0)))
                                       ((vec_access_dec (bytes) (3))))))))) in
   bloom_set_bit (out)
     (Build_bloom_bit_index (((uint
                                 ((concat_vec
                                     ((subrange_vec_dec ((vec_access_dec (bytes) (4))) (2) (0)))
                                     ((vec_access_dec (bytes) (5))))))))).

Definition bloom_add_log_at (bloom : vec (mword 8) 256) (index : log_store_index)
(*(0 <=? index) && (index <=? (2 ^ 64 - 1))*)
: M (LogsBloom) :=
   let index := (index).(log_store_index_value) in
   (log_address (Build_log_store_index ((index)))) >>= fun (w__0 : vec (mword 8) 20) =>
   (keccak256_address (w__0)) >>= fun (w__1 : vec (mword 8) 32) =>
   let out := bloom_add_entry_hash (bloom) (w__1) in
   let topic : Z := 0 in
   ((log_topics_count (Build_log_store_index ((index)))) >>= fun semanticResult =>
    returnM (semanticResult).(log_store_index_value)) >>= fun topic_count =>
   (whileMT
     (out, topic)
     (fun '(out, topic) => Z.sub (topic_count) (topic))
     (fun '(out, topic) => returnM ((Z.ltb (topic) (topic_count))))
     (fun '(out, topic) =>
       (assert_exp' true "loop dummy assert" >>= fun _ =>
        ((log_topic (Build_log_store_index ((index))) (Build_log_store_index ((topic)))) >>= fun semanticResult =>
         returnM (semanticResult).(word_value)) >>= fun (w__2 : Z) =>
        (keccak256_word (Build_word ((w__2)))) >>= fun (w__3 : vec (mword 8) 32) =>
        let out := (bloom_add_entry_hash (out) (w__3))  : vec (mword 8) 256 in
        ((log_store_index_increment (Build_log_store_index ((topic)))) >>= fun semanticResult =>
         returnM (semanticResult).(log_store_index_value)) >>= fun (w__4 : Z) =>
        let topic := w__4  : Z in
        returnM ((out, topic)))
        : M ((vec (mword 8) 256 * Z)))) >>= fun '((out, topic)
   : (vec (mword 8) 256 * Z)) =>
   returnM (out).

Definition bloom_add_logs (bloom : vec (mword 8) 256) (logs : LogSeriesRef) : M (LogsBloom) :=
   let out := bloom in
   let offset : Z := 0 in
   (whileMT
     (offset, out)
     (fun '(offset, out) => Z.sub ((logs.(LogSeriesRef_count)).(log_store_index_value)) (offset))
     (fun '(offset, out) =>
       returnM ((Z.ltb (offset) ((logs.(LogSeriesRef_count)).(log_store_index_value)))))
     (fun '(offset, out) =>
       (assert_exp' true "loop dummy assert" >>= fun _ =>
        ((log_store_index_add
            (Build_log_store_index (((logs.(LogSeriesRef_start)).(log_store_index_value))))
            (Build_log_store_index ((offset)))) >>= fun semanticResult =>
         returnM (semanticResult).(log_store_index_value)) >>= fun (w__0 : Z) =>
        (bloom_add_log_at (out) (Build_log_store_index ((w__0)))) >>= fun (w__1 : vec (mword 8) 256) =>
        let out := w__1  : vec (mword 8) 256 in
        ((log_store_index_increment (Build_log_store_index ((offset)))) >>= fun semanticResult =>
         returnM (semanticResult).(log_store_index_value)) >>= fun (w__2 : Z) =>
        let offset := w__2  : Z in
        returnM ((offset, out)))
        : M ((Z * vec (mword 8) 256)))) >>= fun '((offset, out)
   : (Z * vec (mword 8) 256)) =>
   returnM (out).

Definition logs_bloom_for_logs (logs : LogSeriesRef) : M (LogsBloom) :=
   (bloom_add_logs (EMPTY_LOGS_BLOOM) (logs))  : M (vec (mword 8) 256).

Definition logs_bloom_or (left' : vec (mword 8) 256) (right' : vec (mword 8) 256) : LogsBloom :=
   let out := left' in
   let '(loop_k_lower) := 0 in
   let '(loop_k_upper) := 255 in
   (foreach_Z_up loop_k_lower loop_k_upper 1 out
     (fun k '(out) =>
       vec_update_dec (out) (k)
         ((or_vec ((vec_access_dec (out) (k))) ((vec_access_dec (right') (k))))))).

Definition k_emit_transfer_log (src : vec (mword 8) 20) (dst : vec (mword 8) 20) (v : word)
(*(0 <=? v) && (v <=? (2 ^ 256 - 1))*)
: M (unit) :=
   let v := (v).(word_value) in
   (or_boolM
      (read_reg k_fork >>= fun (w__0 : Fork) => returnM (((fork_lt (w__0) (Amsterdam))  : bool)))
      (returnM (((orb ((word_is_zero (v))) ((generic_eq (src) (dst))))  : bool)))) >>= fun (w__1 : bool) =>
   (if w__1 then returnM (tt)
    else
      (k_log (EIP7708_SYSTEM_ADDRESS)
         ((LogTopics3
             (let '(semanticValue0, semanticValue1, semanticValue2) := (((EIP7708_TRANSFER_TOPIC).(word_value), (address_to_word
                                                                                                                   (src)).(word_value), (address_to_word
                                                                                                                                           (dst)).(word_value))) in ((Build_word (semanticValue0)), (Build_word (semanticValue1)), (Build_word (semanticValue2))))))
         ((LogDataWord (Build_word ((v))))))
       : M (unit))
    : M (unit).

Definition k_emit_burn_log (a : vec (mword 8) 20) (v : word) (*(0 <=? v) && (v <=? (2 ^ 256 - 1))*)
: M (unit) :=
   let v := (v).(word_value) in
   (or_boolM
      (read_reg k_fork >>= fun (w__0 : Fork) => returnM (((fork_lt (w__0) (Amsterdam))  : bool)))
      (returnM (((word_is_zero (v))  : bool)))) >>= fun (w__1 : bool) =>
   (if w__1 then returnM (tt)
    else
      (k_log (EIP7708_SYSTEM_ADDRESS)
         ((LogTopics2
             (let '(semanticValue0, semanticValue1) := (((EIP7708_BURN_TOPIC).(word_value), (address_to_word
                                                                                               (a)).(word_value))) in ((Build_word (semanticValue0)), (Build_word (semanticValue1))))))
         ((LogDataWord (Build_word ((v))))))
       : M (unit))
    : M (unit).

Definition account_info_changed (c : AccountInfo) (o : AccountInfo) : bool :=
   orb
     ((neq_int ((c.(AccountInfo_nonce)).(account_nonce_value))
         ((o.(AccountInfo_nonce)).(account_nonce_value))))
     (((orb
          ((neq_int ((c.(AccountInfo_balance)).(word_value))
              ((o.(AccountInfo_balance)).(word_value))))
          ((orb ((generic_neq (c.(AccountInfo_code_hash)) (o.(AccountInfo_code_hash))))
              ((generic_neq (c.(AccountInfo_storage_root)) (o.(AccountInfo_storage_root)))))))
      : bool)).

Definition account_info_empty (info : AccountInfo) : bool :=
   andb ((generic_eq (info.(AccountInfo_code_hash)) (KECCAK_EMPTY)))
     (((andb ((Z.eqb ((info.(AccountInfo_nonce)).(account_nonce_value)) (0)))
          ((word_is_zero ((info.(AccountInfo_balance)).(word_value)))))
      : bool)).

Definition account_changed (c : Account) (o : Account) : bool :=
   orb ((account_info_changed (c.(Account_info)) (o.(Account_info))))
     ((orb ((neq_bool (c.(Account_present)) (o.(Account_present))))
         ((neq_bool (c.(Account_storage_cleared)) (o.(Account_storage_cleared)))))).

Definition account_set_info (acc : Account) (info : AccountInfo) : Account :=
   if account_info_empty (info) then
     {| Account_info :=
          {[ EMPTY_ACCOUNT_INFO with
            AccountInfo_storage_root := acc.(Account_info).(AccountInfo_storage_root) ]};
        Account_present := false;
        Account_storage_cleared := true;
        Account_created := acc.(Account_created);
        Account_selfdestructed := acc.(Account_selfdestructed) |}
   else
     {| Account_info := info;
        Account_present := true;
        Account_storage_cleared := acc.(Account_storage_cleared);
        Account_created := acc.(Account_created);
        Account_selfdestructed := acc.(Account_selfdestructed) |}.

Definition account_clear_storage (acc : Account) : Account :=
   {[ acc with Account_storage_cleared := true ]}.

Definition account_delete (acc : Account) : Account :=
   {| Account_info :=
        {[ EMPTY_ACCOUNT_INFO with
          AccountInfo_storage_root := acc.(Account_info).(AccountInfo_storage_root) ]};
      Account_present := false;
      Account_storage_cleared := true;
      Account_created := acc.(Account_created);
      Account_selfdestructed := acc.(Account_selfdestructed) |}.

Definition account_clear_preserving_balance (acc : Account) : Account :=
   account_set_info ((account_clear_storage (acc)))
     (let  _record := acc.(Account_info) in
     {| AccountInfo_nonce := (Build_account_nonce (0));
        AccountInfo_balance := _record.(AccountInfo_balance);
        AccountInfo_code_hash := KECCAK_EMPTY;
        AccountInfo_storage_root := _record.(AccountInfo_storage_root) |}).

Definition store_account (a : vec (mword 8) 20) (v : Account) : M (unit) :=
   (acct_tx_update (a) (v))  : M (unit).

Definition store_account_info (a : vec (mword 8) 20) (acc : Account) (info : AccountInfo) : M (unit) :=
   (if account_info_empty (info) return M (unit) then (storage_tx_clear (a))  : M (unit)
    else returnM (tt)) >>
   let next := account_set_info (acc) (info) in
   (if orb
         ((generic_neq (next.(Account_info).(AccountInfo_storage_root))
             (acc.(Account_info).(AccountInfo_storage_root))))
         ((orb ((neq_bool (next.(Account_present)) (acc.(Account_present))))
             ((neq_bool (next.(Account_storage_cleared)) (acc.(Account_storage_cleared))))))
      return
      M (unit) then
      (store_account (a) (next))
       : M (unit)
    else
      (if neq_int ((next.(Account_info).(AccountInfo_balance)).(word_value))
            ((acc.(Account_info).(AccountInfo_balance)).(word_value))
         return
         M (unit) then
         (acct_tx_set_balance (a)
            (Build_word (((next.(Account_info).(AccountInfo_balance)).(word_value)))))
          : M (unit)
       else returnM (tt)) >>
      (if neq_int ((next.(Account_info).(AccountInfo_nonce)).(account_nonce_value))
            ((acc.(Account_info).(AccountInfo_nonce)).(account_nonce_value))
         return
         M (unit) then
         (acct_tx_set_nonce (a)
            (Build_account_nonce (((next.(Account_info).(AccountInfo_nonce)).(account_nonce_value)))))
          : M (unit)
       else returnM (tt)) >>
      (if generic_neq (next.(Account_info).(AccountInfo_code_hash))
            (acc.(Account_info).(AccountInfo_code_hash))
         return
         M (unit) then
         (acct_tx_set_code_hash (a) (next.(Account_info).(AccountInfo_code_hash)))
          : M (unit)
       else returnM (tt))
       : M (unit))
    : M (unit).

Definition k_get_balance (a : vec (mword 8) 20) : M (word) :=
   ((k_aload (a)) >>= fun (w__0 : Account) =>
   returnM ((w__0.(Account_info).(AccountInfo_balance)).(word_value))) >>= fun semanticResult =>
   returnM (Build_word (semanticResult)).

Definition k_get_nonce (a : vec (mword 8) 20) : M (account_nonce) :=
   ((k_aload (a)) >>= fun (w__0 : Account) =>
   returnM ((w__0.(Account_info).(AccountInfo_nonce)).(account_nonce_value))) >>= fun semanticResult =>
   returnM (Build_account_nonce (semanticResult)).

Definition k_account_exists (a : vec (mword 8) 20) : M (bool) :=
   (k_aload (a)) >>= fun (w__0 : Account) => returnM (w__0.(Account_present)).

Definition k_account_is_empty (a : vec (mword 8) 20) : M (bool) :=
   (k_aload (a)) >>= fun (w__0 : Account) => returnM ((account_info_empty (w__0.(Account_info)))).

Definition k_account_occupied (a : vec (mword 8) 20) : M (bool) :=
   (k_aload (a)) >>= fun acc =>
   let info := acc.(Account_info) in
   let anchored_storage :=
     andb ((negb (acc.(Account_storage_cleared))))
       ((generic_neq (info.(AccountInfo_storage_root)) (EMPTY_TRIE_ROOT))) in
   (if orb ((generic_neq (info.(AccountInfo_code_hash)) (KECCAK_EMPTY)))
         (((orb ((neq_int ((info.(AccountInfo_nonce)).(account_nonce_value)) (0)))
              (anchored_storage))
          : bool)) then
      returnM (true)
    else (storage_has_writes (a))  : M (bool))
    : M (bool).

Definition k_transfer (src : vec (mword 8) 20) (dst : vec (mword 8) 20) (v : word)
(*(0 <=? v) && (v <=? (2 ^ 256 - 1))*)
: M (unit) :=
   let v := (v).(word_value) in
   (k_aload (src)) >>= fun src_acc =>
   (k_aload (dst)) >>= fun dst_acc =>
   (if orb ((word_is_zero (v))) ((generic_eq (src) (dst))) then returnM (tt)
    else
      (store_account_info (src) (src_acc)
         ({[ src_acc.(Account_info) with
           AccountInfo_balance :=
             (Build_word ((alu_sub
                             (Build_word (((src_acc.(Account_info).(AccountInfo_balance)).(word_value))))
                             (Build_word ((v)))).(word_value))) ]})) >>
      (store_account_info (dst) (dst_acc)
         ({[ dst_acc.(Account_info) with
           AccountInfo_balance :=
             (Build_word ((alu_add
                             (Build_word (((dst_acc.(Account_info).(AccountInfo_balance)).(word_value))))
                             (v)).(word_value))) ]})) >>
      (k_emit_transfer_log (src) (dst) (Build_word ((v))))
       : M (unit))
    : M (unit).

Definition k_bump_nonce (a : vec (mword 8) 20) : M (unit) :=
   (k_aload (a)) >>= fun cur =>
   ((account_nonce_increment
       (Build_account_nonce (((cur.(Account_info).(AccountInfo_nonce)).(account_nonce_value))))) >>= fun semanticResult =>
    returnM (semanticResult).(account_nonce_value)) >>= fun (w__0 : Z) =>
   (store_account_info (a) (cur)
      ({[ cur.(Account_info) with AccountInfo_nonce := (Build_account_nonce (w__0)) ]}))
    : M (unit).

Definition k_add_balance (a : vec (mword 8) 20) (v : Z) (*(0 <=? v) && (v <? (2 ^ 256))*) : M (unit) :=
   (k_aload (a)) >>= fun cur =>
   (if negb ((word_is_zero (v))) return M (unit) then
      (store_account_info (a) (cur)
         ({[ cur.(Account_info) with
           AccountInfo_balance :=
             (Build_word ((alu_add
                             (Build_word (((cur.(Account_info).(AccountInfo_balance)).(word_value))))
                             (v)).(word_value))) ]}))
       : M (unit)
    else returnM (tt))
    : M (unit).

Definition k_sub_balance (a : vec (mword 8) 20) (v : word) (*(0 <=? v) && (v <=? (2 ^ 256 - 1))*)
: M (unit) :=
   let v := (v).(word_value) in
   (k_aload (a)) >>= fun cur =>
   (if negb ((word_is_zero (v))) return M (unit) then
      (store_account_info (a) (cur)
         ({[ cur.(Account_info) with
           AccountInfo_balance :=
             (Build_word ((alu_sub
                             (Build_word (((cur.(Account_info).(AccountInfo_balance)).(word_value))))
                             (Build_word ((v)))).(word_value))) ]}))
       : M (unit)
    else returnM (tt))
    : M (unit).

Definition k_clear_storage (a : vec (mword 8) 20) : M (unit) :=
   (k_aload (a)) >>= fun cur =>
   (storage_tx_clear (a)) >> (store_account (a) ((account_clear_storage (cur))))  : M (unit).

Definition k_code_key (a : vec (mword 8) 20) : M (hash) :=
   (k_aload (a)) >>= fun (w__0 : Account) => returnM (w__0.(Account_info).(AccountInfo_code_hash)).

Definition k_get_codehash (a : vec (mword 8) 20) : M (hash) :=
   (k_aload (a)) >>= fun acc =>
