Definition blob_base_fee (excess_blob_gas : excess_blob_gas_typ)
(*(0 <=? excess_blob_gas) && (excess_blob_gas <=? (2 ^ 64 - 1))*)
: M (word) :=
   let excess_blob_gas := (excess_blob_gas).(excess_blob_gas_value) in
   (read_reg k_blob_schedule >>= fun (w__0 : BlobSchedule) =>
   let denominator :=
     (w__0.(BlobSchedule_base_fee_update_fraction)).(blob_fee_update_fraction_value) in
   let output_limit := Z.mul ((pow2 (256))) (denominator) in
   let i : Z := 1 in
   let output : Z := 0 in
   let numerator_accum : Z := Z.mul ((MIN_BLOB_BASE_FEE).(word_value)) (denominator) in
   (whileMT
     (i, numerator_accum, output)
     (fun '(i, numerator_accum, output) => Z.sub (output_limit) (output))
     (fun '(i, numerator_accum, output) => returnM ((Z.gtb (numerator_accum) (0))))
     (fun '(i, numerator_accum, output) =>
       (assert_exp' true "loop dummy assert" >>= fun _ =>
        let output : Z := Z.add (output) (numerator_accum) in
        (if Z.leb (output_limit) (output) return M (unit) then
           throw (InvalidBlock (ExecutionInvalid))
         else returnM (tt)) >>
        let numerator_accum : Z :=
          e_div ((Z.mul (numerator_accum) (excess_blob_gas))) ((Z.mul (denominator) (i))) in
        let i : Z := Z.add (i) (1) in
        returnM ((i, numerator_accum, output)))
        : M ((Z * Z * Z)))) >>= fun '((i, numerator_accum, output)
   : (Z * Z * Z)) =>
   let fee := e_div (output) (denominator) in
   (if andb ((Z.leb (0) (fee))) ((Z.ltb (fee) ((pow2 (256))))) then
      returnM (((U256 (fee)).(word_value)))
    else throw (InvalidBlock (ExecutionInvalid)))
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_word (semanticResult)).

