   let parent_blob_gas_used := (parent_blob_gas_used).(blob_gas_used_value) in
   let parent_base_fee_per_gas := (parent_base_fee_per_gas).(word_value) in
   (let parent_blob_gas := Z.add (parent_excess_blob_gas) (parent_blob_gas_used) in
