                   IntrinsicGasCost_calldata_floor := w__2 |}))
    else
      let '(@existT _ _ input__'len (@existT _ _ input__'off input)) :=
        (@existT _ _ _ (@existT _ _ _ (projT2 (projT2 (tx.(Transaction_input_src))))) : {len & {off & (StatelessInputSliceFields off len)}}%type) in
      let recipient := (amsterdam_recipient_execution_cost (tx)).(amsterdam_recipient_cost_value) in
      let address_count :=
        (tx.(Transaction_access_list).(AccessListRef_address_count)).(transaction_item_count_value) in
      let slot_count :=
        (tx.(Transaction_access_list).(AccessListRef_slot_count)).(transaction_item_count_value) in
