              ((Z.add ((Z.mul (AMSTERDAM_ACCESS_LIST_ADDRESS) (address_count)))
                  ((Z.mul (AMSTERDAM_ACCESS_LIST_SLOT) (slot_count)))))
              ((Z.mul (AMSTERDAM_ACCESS_LIST_ADDRESS_FLOOR) (address_count)))))
          ((Z.mul (AMSTERDAM_ACCESS_LIST_SLOT_FLOOR) (slot_count))) in
      let authorization_execution :=
        Z.mul (AMSTERDAM_AUTH_BASE)
          ((tx.(Transaction_authorizations).(AuthorizationListRef_count)).(transaction_item_count_value)) in
      (if tx.(Transaction_is_create) return M (Z) then
         ((transaction_initcode_gas
             (Build_transaction_byte_length ((input.(StatelessInputSliceFields_len))))) >>= fun semanticResult =>
          returnM (semanticResult).(transaction_initcode_cost_value))
          : M (Z)
