      ((calldata_cost (projT2 (projT2 (tx.(Transaction_input_src))))) >>= fun semanticResult =>
       returnM (semanticResult).(transaction_calldata_cost_value)) >>= fun (w__4 : Z) =>
      let execution :=
        Z.add
