Definition transaction_costs (tx : Transaction) (gas_limit : block_gas_limit) (blob_price : word)
(*(0 <=? gas_limit) && (gas_limit <=? (2 ^ 64 - 1))*)
(*(0 <=? blob_price) && (blob_price <=? (2 ^ 256 - 1))*)
