    returnM (semanticResult).(transaction_blob_gas_value)) >>= fun blob_gas =>
   let blob_fee_value := Z.mul (blob_price) (blob_gas) in
   let upfront_value :=
     Z.add
       ((Z.add ((Z.mul ((tx.(Transaction_max_fee)).(word_value)) (gas_limit)))
           ((tx.(Transaction_value)).(word_value))))
       ((Z.mul ((tx.(Transaction_max_blob_fee)).(word_value)) (blob_gas))) in
   (if andb ((Z.ltb (blob_fee_value) ((pow2 (256))))) ((Z.ltb (upfront_value) ((pow2 (256))))) then
      returnM (({| TransactionCosts_intrinsic_execution := intrinsic.(IntrinsicGasCost_execution);
                   TransactionCosts_intrinsic_state := intrinsic.(IntrinsicGasCost_state);
                   TransactionCosts_calldata_floor := intrinsic.(IntrinsicGasCost_calldata_floor);
                   TransactionCosts_blob_gas := (Build_transaction_blob_gas (blob_gas));
                   TransactionCosts_blob_fee :=
                     (Build_word ((protocol_word (blob_fee_value)).(word_value)));
                   TransactionCosts_upfront :=
                     (Build_word ((protocol_word (upfront_value)).(word_value))) |}))
    else throw (InvalidBlock (ExecutionInvalid)))
    : M (TransactionCosts).

