       ((_rec_process_auth_cursor _ _ (next) ((Z.sub (_reclimit) (1)))
           (_limit_reduces_bool _acc ltac:(assumption))) >>= fun semanticResult =>
        returnM (semanticResult).(gas_refund_value)) >>= fun (w__2 : Z) =>
