Definition enter_system_call_frame (tgt : vec (mword 8) 20) (input : CalldataSlice)
: M (journal_checkpoint) :=
   (k_state_checkpoint (tt)) >>= fun checkpoint =>
   write_reg pc (0) >>
   write_reg call_depth (Build_frame_depth ((0))) >>
   write_reg gas_remaining (SYSTEM_CALL_GAS_LIMIT) >>
   write_reg state_gas_remaining (GAS_ZERO) >>
   write_reg
     state_gas_spilled
     (Build_state_gas_spill (((STATE_GAS_SPILL_ZERO).(state_gas_spill_value)))) >>
   write_reg frame_refund (Build_gas_refund (((GAS_REFUND_ZERO).(gas_refund_value)))) >>
   (stack_reset (tt)) >>
   (returndata_clear (tt)) >>
   write_reg frame_status ((Running (tt))) >>
   write_reg calldata (input) >>
   write_reg
     message
     (({| Message_caller := SYSTEM_ADDRESS;
          Message_address := tgt;
          Message_code_address := tgt;
          Message_value := (Build_word ((ZERO_WORD).(word_value)));
          Message_state_gas_reservoir := GAS_ZERO;
          Message_is_static := false;
          Message_depth := (Build_frame_depth (0)) |})) >>
   (k_code_key (tgt)) >>= fun (w__0 : vec (mword 8) 32) =>
   (code_db_resolve (w__0)) >>= fun (w__1 : Code) =>
   write_reg frame_code (w__1) >> returnM (checkpoint).

