   (if fork_gteq (w__2) (Prague) return M (unit) then
      read_reg k_header >>= fun (w__3 : BlockHeader) =>
      (system_call (HISTORY_STORAGE_ADDR) (w__3.(BlockHeader_parent_hash)))
       : M (unit)
    else returnM (tt))
