                 | StatelessPayloadInvalid failure =>
                    let '(_) :=
                      (validation_debug_record
                         (Build_validation_stage (((failure.(StatelessValidationFailure_stage)).(validation_stage_value))))
                         (failure.(StatelessValidationFailure_reason)))
