                    false
                 end in
               returnM ((Some
                           (({| GuestValidation_input_ref := input_ref;
                                GuestValidation_valid := valid |}))))) (fun __catch_val => match __catch_val with 
    | InvalidBlock reason =>
       let '(_) :=
